from enum import Enum, auto
from dataclasses import dataclass
from typing import List, Optional, Union

class TokenType(Enum):
    NUMBER = auto()
    IDENTIFIER = auto()
    PLUS = auto()
    MINUS = auto()
    MULTIPLY = auto()
    DIVIDE = auto()
    LPAREN = auto()
    RPAREN = auto()
    EOF = auto()

@dataclass
class Token:
    type: TokenType
    value: Union[str, int, float]

# AST Node Classes
@dataclass
class NumberNode:
    value: Union[int, float]

@dataclass
class IdentifierNode:
    name: str

@dataclass
class BinaryOpNode:
    operator: str
    left: 'ASTNode'
    right: 'ASTNode'

ASTNode = Union[NumberNode, IdentifierNode, BinaryOpNode]

class Parser:
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0

    def current(self) -> Token:
        return self.tokens[self.pos] if self.pos < len(self.tokens) else Token(TokenType.EOF, None)

    def consume(self, expected: TokenType = None) -> Token:
        token = self.current()
        if expected and token.type != expected:
            raise SyntaxError(f'Expected {expected}, got {token.type}')
        self.pos += 1
        return token

    def parse(self) -> ASTNode:
        """Entry point: parse an expression"""
        return self.parse_expression()

    def parse_expression(self) -> ASTNode:
        """
        Expression → Term { ('+' | '-') Term }
        Handles low-precedence + and -
        """
        left = self.parse_term()

        while self.current().type in (TokenType.PLUS, TokenType.MINUS):
            op_token = self.consume()
            right = self.parse_term()
            left = BinaryOpNode(op_token.value, left, right)

        return left

    def parse_term(self) -> ASTNode:
        """
        Term → Factor { ('*' | '/') Factor }
        Handles high-precedence * and /
        """
        left = self.parse_factor()

        while self.current().type in (TokenType.MULTIPLY, TokenType.DIVIDE):
            op_token = self.consume()
            right = self.parse_factor()
            left = BinaryOpNode(op_token.value, left, right)

        return left

    def parse_factor(self) -> ASTNode:
        """
        Factor → NUMBER | IDENTIFIER | '(' Expression ')'
        Base case: literals, variables, or parenthesized expressions
        """
        token = self.current()

        if token.type == TokenType.NUMBER:
            self.consume()
            return NumberNode(token.value)

        elif token.type == TokenType.IDENTIFIER:
            self.consume()
            return IdentifierNode(token.value)

        elif token.type == TokenType.LPAREN:
            self.consume()  # (
            expr = self.parse_expression()
            self.consume(TokenType.RPAREN)  # )
            return expr

        else:
            raise SyntaxError(f'Unexpected token: {token}')

    def print_ast(self, node: ASTNode, indent: int = 0):
        prefix = '  ' * indent
        if isinstance(node, NumberNode):
            print(f'{prefix}Number({node.value})')
        elif isinstance(node, IdentifierNode):
            print(f'{prefix}Identifier({node.name})')
        elif isinstance(node, BinaryOpNode):
            print(f'{prefix}BinaryOp({node.operator})')
            self.print_ast(node.left, indent + 1)
            self.print_ast(node.right, indent + 1)

# Example usage
tokens = [
    Token(TokenType.NUMBER, 3),
    Token(TokenType.PLUS, '+'),
    Token(TokenType.NUMBER, 4),
    Token(TokenType.MULTIPLY, '*'),
    Token(TokenType.NUMBER, 5),
    Token(TokenType.EOF, None)
]

parser = Parser(tokens)
ast = parser.parse()
print('AST for: 3 + 4 * 5')
parser.print_ast(ast)
# Output shows 3 + (4 * 5), demonstrating precedence!
